// Public types and constants for artifacts generated by @kiskadee/web-builder.
//
// This module is intentionally side-effect free so it can be safely
// imported from other packages (e.g., @kiskadee/showcase) without
// triggering any build logic.

export const SYSTEM_UI_FONT_STACK =
  'system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif';

export type {
  ComponentClassNameMap,
  ComponentClassNameMapSplit
} from './src/phase-5-generate-class-names-map/generateClassNamesMap';

// JSON structure produced by phase-8 writeExtraArtifacts step.
//
// Currently, it exposes the focusColor token resolved per design system,
// segment, and theme, plus an optional background color.
export type ExtraArtifactsJSON = {
  focusColor: string;
  background?: string;
};

// Manifest types (phase-7 publishMetadata) describing high-level
// capabilities by design system.
export type {
  Manifest,
  ManifestComponent,
  ManifestComponentState
} from './src/phase-7-publish-metadata/manifestTypes';
